class LinguistLive:
    """
    Real-time Language Learning Partner powered by Gemini 2.5 Flash Native Audio.
    """
    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.environ.get("API_KEY")
        if not self.api_key:
            raise ValueError("API_KEY must be set in environment variables.")

        self.client = genai.Client(
            api_key=self.api_key,
            http_options={'api_version': 'v1alpha'}
        )
        self.model_id = "gemini-2.5-flash-native-audio-preview-12-2025"

    def _get_system_instruction(self, language: str, scenario_id: str, level: str) -> str:
        scenario = SCENARIOS.get(scenario_id, SCENARIOS["casual"])

        level_guidelines = {
            'Beginning': 'Speak VERY SLOWLY. Use simple basic vocabulary. If the user makes a mistake, gently explain it. Use short sentences.',
            'Intermediate': 'Speak at a moderate, clear pace. Use standard vocabulary and some common idioms. Focus on natural conversation flow but remain helpful.',
            'Advanced': 'Speak at a native speed. Use complex vocabulary, slang, and cultural references. Challenge the user.'
        }

        latin_rules = ""
        if language.lower() == "latin":
            latin_rules = """
            LATIN SPECIFIC RULES:
            1. PRONUNCIATION: Use strictly CLASSICAL (RESTORED) pronunciation. Do NOT use Ecclesiastical pronunciation.
               - Hard 'c' (/k/), 'v' sounds like /w/, 'ae' sounds like /ai/.
            2. WRITING: You MUST include macrons (ā, ē, ī, ō, ū, ȳ) for all printed text.
            """

        return f"""
        You are an immersive language practice partner for someone learning {language}.
        The user's proficiency level is: {level}.
        The current scenario is: {scenario['title']}.
        Instruction for you: {scenario['instruction']}

        Guidelines for {level} level:
        {level_guidelines.get(level, 'Speak clearly.')}

        General Rules:
        - SPEAK ONLY IN {language}. 
        - Keep the conversation flowing naturally as a partner in the role-play.
        - Be enthusiastic and patient.
        - Start by greeting the user and initiating the scenario immediately in {language}.
        {latin_rules}
        """

    async def run_session(self, language: str = "Latin", scenario_id: str = "cafe", level: str = "Intermediate"):
        """
        Starts an asynchronous session with the Gemini Live API.
        """
        system_instruction = self._get_system_instruction(language, scenario_id, level)

        config = types.LiveConnectConfig(
            model=self.model_id,
            system_instruction=system_instruction,
            speech_config=types.SpeechConfig(
                voice_config=types.VoiceConfig(
                    prebuilt_voice_config=types.PrebuiltVoiceConfig(voice_name='Kore')
                )
            ),
            # Enable transcriptions for accessibility
            input_audio_transcription=types.InputAudioTranscription(),
            output_audio_transcription=types.OutputAudioTranscription(),
        )

        print(f"Connecting to LinguistLive AI ({language} - {level})...")

        async with self.client.aio.live.connect(model=self.model_id, config=config) as session:
            print(f"Connected! Scenario: {SCENARIOS[scenario_id]['title']}")

            async for message in session.receive():
                if message.server_content and message.server_content.model_turn:
                    for part in message.server_content.model_turn.parts:
                        if part.inline_data:
                            print("[AI is speaking...]")

                if message.server_content and message.server_content.output_transcription:
                    print(f"AI: {message.server_content.output_transcription.text}")

                if message.server_content and message.server_content.input_transcription:
                    print(f"You: {message.server_content.input_transcription.text}")

                if message.server_content and message.server_content.interrupted:
                    print("[Conversation Interrupted]")

